import sys
from collections import deque

sys.setrecursionlimit(30000)


def main():
    read = sys.stdin.buffer.readline
    n, m = map(int, read().split())

    roads = [[] for _ in range(n)]
    weights = set()

    for _ in range(m):
        airport, factory, days = map(int, read().split())
        roads[airport - 1].append((factory - 1, days))
        weights.add(days)

    if any(not edges for edges in roads):
        print(-1)
        return

    thresholds = sorted(weights)

    def feasible(limit):
        graph = [
            [factory for factory, days in edges if days <= limit]
            for edges in roads
        ]
        if any(not edges for edges in graph):
            return False

        left_match = [-1] * n
        right_match = [-1] * n
        matched = 0
        distance = [-1] * n
        position = [0] * n
        shortest = n + 1

        def augment(airport):
            edges = graph[airport]
            while position[airport] < len(edges):
                factory = edges[position[airport]]
                position[airport] += 1
                other = right_match[factory]

                if other == -1:
                    if distance[airport] + 1 != shortest:
                        continue
                elif (
                    distance[other] != distance[airport] + 1
                    or not augment(other)
                ):
                    continue

                left_match[airport] = factory
                right_match[factory] = airport
                return True

            distance[airport] = -1
            return False

        while matched < n:
            queue = deque()
            for airport in range(n):
                if left_match[airport] == -1:
                    distance[airport] = 0
                    queue.append(airport)
                else:
                    distance[airport] = -1

            shortest = n + 1

            while queue:
                airport = queue.popleft()
                next_distance = distance[airport] + 1
                if next_distance > shortest:
                    continue

                for factory in graph[airport]:
                    other = right_match[factory]
                    if other == -1:
                        shortest = next_distance
                    elif next_distance < shortest and distance[other] == -1:
                        distance[other] = next_distance
                        queue.append(other)

            if shortest == n + 1:
                return False

            position = [0] * n
            for airport in range(n):
                if left_match[airport] == -1 and augment(airport):
                    matched += 1

        return True

    low, high = 0, len(thresholds)
    while low < high:
        middle = (low + high) // 2
        if feasible(thresholds[middle]):
            high = middle
        else:
            low = middle + 1

    print(thresholds[low] if low < len(thresholds) else -1)


if __name__ == "__main__":
    main()
